// Generated by scripts/extract-ai-catalog.mjs; preserve the HTML matcher.

function clonePodarkusData(value) { return JSON.parse(JSON.stringify(value)); }
/* Offline equivalent of the local catalogue matcher; no network or storage. */
export function createPodarkusLocal(data, aiCandidates = false) {
  const norm = text => text.toLowerCase().replaceAll('ё','е').replace(/[—–]/g,'-').replace(/\s+/g,' ').trim();
  const escape = text => text.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  const word = '[\\p{L}\\p{N}_]';
  const boundary = `(?:(?<!${word})(?=${word})|(?<=${word})(?!${word}))`;
  const rx = (source, flags = '') => new RegExp(source.replaceAll('\\b',boundary).replaceAll('\\w',word), 'u'+flags);
  // Literal keyword lookup avoids compiling thousands of Unicode regexes on a cold start.
  const wordBefore = /[\p{L}\p{N}_]$/u, wordAfter = /^[\p{L}\p{N}_]/u;
  const aliasRx = alias => {
    const value = norm(alias), prefix = value.endsWith('*'), needle = value.replace(/\*+$/,'');
    const exec = text => {
      let index = text.indexOf(needle);
      while (index !== -1) {
        if (!wordBefore.test(text.slice(0,index)) && (prefix || !wordAfter.test(text.slice(index+needle.length)))) return {index};
        index = text.indexOf(needle,index+1);
      }
      return null;
    };
    return {exec, test:text=>exec(text)!==null};
  };
  const negativeRx = rx(data.negative_pattern);
  const noExclusionRx = rx(data.no_exclusion_pattern, 'g');
  const aliases = data.aliases.map(([category, alias]) => [category,aliasRx(alias)]);
  const exclusionAliases = data.exclusion_aliases.map(([id,alias]) => [id,aliasRx(alias)]);
  const details = data.details.map(([label,category,aliases,ids]) => ({label,category,patterns:aliases.map(aliasRx),ids}));
  const ignored = new Set(data.ignore_words);
  const sorted = values => [...values].sort();
  const intersects = (values, set) => values.some(value=>set.has(value));

  function validate(payload) {
    if (!payload || typeof payload !== 'object' || Array.isArray(payload)) throw new Error('Ожидается заполненная анкета.');
    const a = {};
    for (const [name,maximum] of [['recipient',100],['occasion',100],['style',30],['exclude',1500],['interests',2000]]) {
      const value = payload[name] === undefined && name === 'exclude' ? '' : payload[name];
      if (typeof value !== 'string' || [...value].length > maximum || (name !== 'exclude' && !value.trim())) throw new Error('Проверьте ответы: обязательные поля не должны быть пустыми или слишком длинными.');
      a[name] = value.trim();
    }
    for (const name of ['recipient','occasion','style']) {
      const option = data.config.questions[name].find(option=>option.value===a[name]);
      if (!option) throw new Error('Выберите получателя, повод и стиль из предложенных вариантов.');
      a[name+'_group'] = option.match_group;
    }
    if (!['string','number'].includes(typeof payload.budget) || !/^[0-9]{1,8}$/.test(String(payload.budget)) || Number(payload.budget)<1 || Number(payload.budget)>10000000) throw new Error('Укажите бюджет целым числом от 1 до 10 000 000 ₽.');
    a.budget = Number(payload.budget);
    const codes = payload.exclude_codes === undefined ? [] : payload.exclude_codes;
    if (!Array.isArray(codes) || codes.length>30 || codes.some(code=>typeof code!=='string')) throw new Error('Проверьте выбранные ограничения.');
    if (codes.some(code=>!Object.hasOwn(data.rule_labels,code))) throw new Error('Неизвестное ограничение.');
    a.exclude_codes = codes;
    a.gift_kind = payload.gift_kind === undefined ? 'any' : payload.gift_kind;
    if (!['any','item','experience'].includes(a.gift_kind)) throw new Error('Выберите вещь, впечатление или любой формат подарка.');
    a.age_group = payload.age_group === undefined ? 'unknown' : payload.age_group;
    if (typeof a.age_group !== 'string' || !Object.hasOwn(data.ages,a.age_group)) throw new Error('Выберите возрастную категорию или вариант «Не знаю».');
    if (a.age_group==='child') a.recipient_group='child';
    else if (['teen','adult','senior'].includes(a.age_group) && a.recipient_group==='child') a.recipient_group='general';
    return a;
  }

  function recommend(payload) {
    const a=validate(payload), positive=new Set(), negative=new Set();
    for (const clause of norm(a.interests).split(rx('[,;.!?\\n]|\\b(?:но|зато|однако)\\b'))) {
      const neg=negativeRx.exec(clause);
      for (const [category,pattern] of aliases) {
        const match=pattern.exec(clause);
        if (match) (neg && neg.index<match.index ? negative : positive).add(category);
      }
    }
    for (const category of negative) positive.delete(category);
    const detailMatches=[], negativeDetails=new Set();
    for (const clause of norm(a.interests).split(rx('[,;.!?\\n]|\\b(?:но|зато|однако|а)\\b'))) {
      for (const detail of details) {
        if (detail.patterns.some(pattern=>pattern.test(clause))) {
          if (negativeRx.test(clause)) negativeDetails.add(detail.label);
          else if (!detailMatches.some(row=>row.label===detail.label)) detailMatches.push(detail);
        }
      }
    }
    const matchedDetails=detailMatches.filter(row=>!negativeDetails.has(row.label));
    for (const detail of matchedDetails) if (!negative.has(detail.category)) positive.add(detail.category);
    const restrictions=norm(a.exclude).replace(noExclusionRx,''), ruleIds=new Set(a.exclude_codes);
    for (const [id,pattern] of exclusionAliases) if (pattern.test(restrictions)) ruleIds.add(id);
    const blocks=new Set(data.blocks.filter(([id])=>ruleIds.has(id)).map(([,block])=>block));
    const blockedTags=new Set([...negative,...[...blocks].filter(b=>b.startsWith('tag:')).map(b=>b.slice(4))]);
    const blockedFlags=new Set([...blocks].filter(b=>!b.startsWith('tag:')));
    const tokenPatterns=(restrictions.match(/[а-яa-z]{4,}/g)||[]).filter(t=>!ignored.has(t)).map(t=>rx('(?<!\\w)'+escape(t.slice(0,t.length>5?5:4))+'\\w*'));
    const ranked=[];
    for (const gift of data.gifts) {
      if (!gift.active || gift.price_max>a.budget) continue;
      const {tags,flags,audiences,occasions}=gift;
      if (!audiences.includes(a.recipient_group) && !audiences.includes('all')) continue;
      if (['child','teen'].includes(a.age_group)) {
        if (flags.includes('knife') || flags.includes('needle')) continue;
        if (a.age_group==='teen' && flags.includes('experience') && !audiences.some(x=>['all','child'].includes(x))) continue;
      }
      if (['teen','adult','senior'].includes(a.age_group) && ['kids-book','kids-puzzle'].includes(gift.id)) continue;
      if (intersects(tags,blockedTags) || intersects(flags,blockedFlags)) continue;
      const isExperience=flags.includes('experience');
      if (a.gift_kind==='item' && (isExperience || flags.includes('certificate'))) continue;
      if (a.gift_kind==='experience' && !isExperience) continue;
      if (tokenPatterns.some(pattern=>pattern.test(norm(gift.title)))) continue;
      const matched=tags.filter(tag=>positive.has(tag));
      if (!aiCandidates && positive.size && !matched.length) continue;
      if (!aiCandidates && !positive.size && !tags.includes('general') && !occasions.includes(a.occasion_group)) continue;
      const reasons=[];
      let score=Math.min(matched.length,3)*24;
      const specific=matchedDetails.filter(d=>d.ids.includes(gift.id) && !blockedTags.has(d.category)).map(d=>d.label);
      if (specific.length) {
        score+=36*Math.min(specific.length,2);
        reasons.push('Уточнение из вашего описания: '+specific.join(', ').toLowerCase());
      }
      reasons.push(matched.length ? 'По интересам: '+sorted(matched).map(t=>data.labels[t].toLowerCase()).join(', ') : 'Нейтральная идея по анкете; совпадение с увлечениями не найдено');
      if (audiences.includes(a.recipient_group)) { score+=9; reasons.push('Подходит выбранному получателю'); }
      if (a.occasion_group!=='general' && occasions.includes(a.occasion_group)) { score+=10; reasons.push('Подходит к поводу «'+a.occasion+'»'); }
      if (a.style===gift.style) { score+=12; reasons.push({minimal:'Лаконичный стиль',maximal:'Яркое оформление',balanced:'Сбалансированный стиль'}[gift.style]); }
      else if (gift.style==='balanced' || a.style==='unknown') score+=2;
      else if (['minimal','maximal'].includes(a.style)) reasons.push('Стиль отличается от выбранного — альтернативный вариант');
      reasons.push('Верхняя граница ориентировочной цены укладывается в бюджет');
      if (a.age_group!=='unknown') reasons.push('Возраст учтён: '+data.ages[a.age_group].toLowerCase());
      const {tags:unusedTags,flags:unusedFlags,audiences:unusedAudiences,occasions:unusedOccasions,...publicGift}=gift;
      // Match Python urlencode (including unescaped ~ and escaped punctuation).
      const query=encodeURIComponent(gift.search_query+' до '+a.budget+' рублей').replace(/[!'()*]/g,c=>'%'+c.charCodeAt(0).toString(16).toUpperCase()).replace(/%20/g,'+');
      ranked.push({...publicGift,reasons,score,categories:sorted(tags).map(t=>data.labels[t]),gift_kind:isExperience?'experience':flags.includes('certificate')?'certificate':'item',search_url:'https://yandex.ru/search/?text='+query});
    }
    ranked.sort((a,b)=>b.score-a.score || a.price_max-b.price_max || (a.id<b.id?-1:a.id>b.id?1:0));
    const warnings=[];
    if (!positive.size) warnings.push(data.messages.unknown);
    if (restrictions || ruleIds.size) warnings.push(data.messages.exclusions);
    return {items:ranked.slice(0,aiCandidates ? data.gifts.length : 6),total_matches:ranked.length,catalog_count:data.config.gift_count,
      recognized_interests:sorted(positive).map(t=>data.labels[t]),negative_interests:sorted(negative).map(t=>data.labels[t]),
      recognized_details:matchedDetails.filter(d=>!blockedTags.has(d.category)).map(d=>d.label),
      applied_exclusions:sorted(ruleIds).map(id=>data.rule_labels[id]),warnings,price_note:data.messages.price,
      empty_message:ranked.length?'':data.messages.empty};
  }
  return {
    recommend,
    request(path,options={}) {
      if (path==='/api/questions') return clonePodarkusData(data.config);
      if (path==='/api/recommendations') return recommend(JSON.parse(options.body));
      throw new Error('Неизвестный запрос к встроенному каталогу.');
    }
  };
}
